      staleMs: 2_000,
      pollMs: 10,
      requireHolderToken: true,
      classifyExistingLock: classifyManagedHostRunTerminalLock,
      holderInfo: {
        pid: process.pid,
        hostname: hostname(),
        command: `managed reconcile ${paths.dir}`,
