function isolatedProcessGroupAlive(pgid: number | null): boolean {
  if (process.platform === 'win32' || !pgid || pgid <= 0) return false;
  try {
    process.kill(-pgid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function signalIsolatedProcessGroup(pgid: number | null, signal: NodeJS.Signals): boolean {
  if (process.platform === 'win32' || !pgid || pgid <= 0) return false;
  try {
    process.kill(-pgid, signal);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ESRCH') return true;
    return false;
